1	/**
2	 * @module useRealtimeUpdates
3	 *
4	 * Hook que assina canais Supabase Realtime para mudanças em
5	 * `movimentacoes`, `estoque` e `alertas_estoque`, disparando
6	 * um callback sempre que qualquer tabela é modificada.
7	 */
8	
9	import { useEffect, useRef } from 'react';
10	import { supabase } from '@/integrations/supabase/client';
11	
12	/**
13	 * Assina canais Supabase Realtime nas tabelas `movimentacoes`, `estoque`
14	 * e `alertas_estoque`. Qualquer INSERT/UPDATE/DELETE dispara `onUpdate`.
15	 *
16	 * Remove automaticamente os canais ao desmontar o componente.
17	 *
18	 * @param onUpdate - Callback opcional executado a cada mudança detectada.
19	 */
20	export function useRealtimeUpdates(onUpdate?: () => void) {
21	  // Ref para o callback evita re-subscribe quando o pai não memoiza
22	  const onUpdateRef = useRef(onUpdate);
23	  onUpdateRef.current = onUpdate;
24	
25	  useEffect(() => {
26	    // Subscribe to movements changes
27	    const movementsChannel = supabase
28	      .channel('movements-changes')
29	      .on(
30	        'postgres_changes',
31	        {
32	          event: '*',
33	          schema: 'public',
34	          table: 'movimentacoes',
35	        },
36	        () => {
37	          onUpdateRef.current?.();
38	        },
39	      )
40	      .subscribe();
41	
42	    // Subscribe to stock changes
43	    const stockChannel = supabase
44	      .channel('stock-changes')
45	      .on(
46	        'postgres_changes',
47	        {
48	          event: '*',
49	          schema: 'public',
50	          table: 'estoque',
51	        },
52	        () => {
53	          onUpdateRef.current?.();
54	        },
55	      )
56	      .subscribe();
57	
58	    // Subscribe to alerts changes
59	    const alertsChannel = supabase
60	      .channel('alerts-changes')
61	      .on(
62	        'postgres_changes',
63	        {
64	          event: '*',
65	          schema: 'public',
66	          table: 'alertas_estoque',
67	        },
68	        () => {
69	          onUpdateRef.current?.();
70	        },
71	      )
72	      .subscribe();
73	
74	    return () => {
75	      supabase.removeChannel(movementsChannel);
76	      supabase.removeChannel(stockChannel);
77	      supabase.removeChannel(alertsChannel);
78	    };
79	  }, []);
80	}
