import { serve } from 'https://deno.land/std@0.168.0/http/server.ts'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
}

const API = 'https://lx-degust-api-integracao-prd.azurewebsites.net'
const FRANQUIA = 3489

// Degust loja code -> our loja_id mapping
const DEGUST_TO_LOJA: Record<number, number> = { 1: 4, 2: 5 }
const LOJA_TO_DEGUST: Record<number, number> = { 4: 1, 5: 2 }

interface TicketMedioRow {
  data: string           // "2026-03-08T00:00:00"
  desconto: number
  descontoReshop: number
  totalFaturado: number
  totalCupons: number
  ticketMedio: number
  quantidadeProdutos: number
  nomeFantasia: string
  codigoLoja: number
}

interface FlashVendaRow {
  codigoFranquia: number
  codigoLoja: number
  nomeFantasia: string
  dataCaixa: string       // "03/09/2026 00:00:00"
  ultimaAtualizacao: string
  previsaoAtualizacao: string
  totalVendas: number
  totalCupons: number
  ticketMedio: number
  quantidadeProduto: number
  caixaAberto: string     // "S" | "N"
}

interface DegustTransaction {
  codigoLoja: string
  nomeLoja: string
  dataCaixa: string
  hora: string
  codigoProduto: string
  nomeProduto: string
  quantidade: number
  valorUnitario: number
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders })
  }

  try {
    const TOKEN = Deno.env.get('DEGUST_API_TOKEN')
    if (!TOKEN) {
      return new Response(
        JSON.stringify({ error: 'DEGUST_API_TOKEN not configured' }),
        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      )
    }

    const apiHeaders = { 'Authorization': `Bearer ${TOKEN}` }
    const { startDate, endDate, lojaId, includeProducts = false } = await req.json()

    if (!startDate || !endDate) {
      return new Response(
        JSON.stringify({ error: 'startDate and endDate required (YYYY-MM-DD)' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      )
    }

    const degustCode = lojaId ? LOJA_TO_DEGUST[lojaId] : undefined

    // ── 1) Flash Vendas (live today for all stores) ──
    let flashData: FlashVendaRow[] = []
    try {
      const flashResp = await fetch(
        `${API}/api/financeiro/flash-vendas?codigoFranqueador=${FRANQUIA}&api-version=1.0`,
        { headers: apiHeaders }
      )
      if (flashResp.ok) {
        flashData = await flashResp.json()
      } else if (flashResp.status === 401) {
        throw new Error('TOKEN_EXPIRED')
      }
    } catch (e) {
      if ((e as Error).message === 'TOKEN_EXPIRED') throw e
      console.error('[degust-pos] flash-vendas error:', e)
    }

    // ── 2) Ticket Medio (daily breakdown for date range) ──
    const storeCodes = degustCode ? [degustCode] : [1, 2]
    const dailyData: TicketMedioRow[] = []

    for (const code of storeCodes) {
      try {
        const tmResp = await fetch(
          `${API}/api/financeiro/ticket-medio?CodigoFranquia=${FRANQUIA}&CodigoLoja=${code}&DataInicial=${startDate}&DataFinal=${endDate}&api-version=1.0`,
          { headers: apiHeaders }
        )
        if (tmResp.ok) {
          const rows: TicketMedioRow[] = await tmResp.json()
          dailyData.push(...rows)
        } else if (tmResp.status === 401) {
          throw new Error('TOKEN_EXPIRED')
        }
      } catch (e) {
        if ((e as Error).message === 'TOKEN_EXPIRED') throw e
        console.error(`[degust-pos] ticket-medio loja ${code} error:`, e)
      }
    }

    // ── 3) Product detail (optional, for a specific date) ──
    let productData: DegustTransaction[] = []
    if (includeProducts && degustCode) {
      // Fetch for the most recent date requested (usually single day drill-down)
      try {
        const prodResp = await fetch(
          `${API}/api/financeiro/movimentacao-produtos?CodigoFranquia=${FRANQUIA}&CodigoLoja=${degustCode}&DataCaixa=${endDate}&api-version=1.0`,
          { headers: apiHeaders }
        )
        if (prodResp.ok) {
          productData = await prodResp.json()
        } else if (prodResp.status === 401) {
          throw new Error('TOKEN_EXPIRED')
        }
      } catch (e) {
        if ((e as Error).message === 'TOKEN_EXPIRED') throw e
        console.error('[degust-pos] movimentacao-produtos error:', e)
      }
    }

    // ── Transform data ──

    // Flash → normalized per store
    const flash = flashData.map(f => ({
      loja_id: DEGUST_TO_LOJA[f.codigoLoja] || f.codigoLoja,
      nome_loja: f.nomeFantasia,
      total_vendas: f.totalVendas,
      total_cupons: f.totalCupons,
      ticket_medio: f.ticketMedio,
      qtd_produtos: f.quantidadeProduto,
      caixa_aberto: f.caixaAberto === 'S',
      ultima_atualizacao: f.ultimaAtualizacao,
    }))

    // Daily → normalized and sorted
    const daily = dailyData.map(d => {
      const dateStr = d.data.split('T')[0] // "2026-03-08T00:00:00" -> "2026-03-08"
      return {
        data: dateStr,
        loja_id: DEGUST_TO_LOJA[d.codigoLoja] || d.codigoLoja,
        nome_loja: d.nomeFantasia,
        total_faturado: d.totalFaturado,
        total_cupons: d.totalCupons,
        ticket_medio: d.ticketMedio,
        desconto: d.desconto,
        qtd_produtos: d.quantidadeProdutos,
      }
    }).sort((a, b) => b.data.localeCompare(a.data))

    // Products → group by hora to approximate individual tickets
    const tickets: { hora: string; items: { produto: string; qtd: number; valor: number }[]; total: number }[] = []
    if (productData.length > 0) {
      const byHour: Record<string, DegustTransaction[]> = {}
      for (const tx of productData) {
        const key = tx.hora
        if (!byHour[key]) byHour[key] = []
        byHour[key].push(tx)
      }
      for (const [hora, txns] of Object.entries(byHour).sort(([a], [b]) => a.localeCompare(b))) {
        const items = txns.map(t => ({
          produto: t.nomeProduto,
          qtd: t.quantidade,
          valor: t.quantidade * t.valorUnitario,
        }))
        tickets.push({
          hora,
          items,
          total: items.reduce((s, i) => s + i.valor, 0),
        })
      }
    }

    // ── Aggregated totals ──
    const filteredDaily = degustCode
      ? daily.filter(d => d.loja_id === lojaId)
      : daily

    const totals = {
      total_faturado: filteredDaily.reduce((s, d) => s + d.total_faturado, 0),
      total_cupons: filteredDaily.reduce((s, d) => s + d.total_cupons, 0),
      total_desconto: filteredDaily.reduce((s, d) => s + d.desconto, 0),
      total_produtos: filteredDaily.reduce((s, d) => s + d.qtd_produtos, 0),
      ticket_medio: 0,
      dias_com_venda: filteredDaily.filter(d => d.total_faturado > 0).length,
    }
    totals.ticket_medio = totals.total_cupons > 0
      ? Math.round((totals.total_faturado / totals.total_cupons) * 100) / 100
      : 0

    return new Response(JSON.stringify({
      flash,
      daily,
      tickets,
      totals,
      meta: {
        startDate,
        endDate,
        lojaId: lojaId || 'all',
        dailyRows: daily.length,
        flashStores: flash.length,
        ticketCount: tickets.length,
      },
    }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    })

  } catch (err) {
    const message = (err as Error).message
    const status = message === 'TOKEN_EXPIRED' ? 401 : 500

    return new Response(
      JSON.stringify({
        error: message === 'TOKEN_EXPIRED'
          ? 'Token Degust expirado. Atualize com: supabase secrets set DEGUST_API_TOKEN="<novo_token>"'
          : `Internal error: ${message}`,
      }),
      { status, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    )
  }
})"}]}

