2	import { useQuery, useQueryClient } from '@tanstack/react-query';
3	import { supabase } from '@/integrations/supabase/client';
4	
5	const sb = supabase as any;
6	
7	export function useAdminOnlineNow() {
8	  const queryClient = useQueryClient();
9	
10	  const sessions = useQuery({
11	    queryKey: ['admin', 'online-sessions'],
12	    queryFn: async () => {
13	      const twoMinAgo = new Date(Date.now() - 2 * 60 * 1000).toISOString();
14	
15	      // Fetch online sessions
16	      const { data: sessionData } = await sb
17	        .from('user_sessions')
18	        .select('*')
19	        .eq('is_online', true)
20	        .gte('last_activity', twoMinAgo)
21	        .order('last_activity', { ascending: false });
22	
23	      if (!sessionData || sessionData.length === 0) return [];
24	
25	      // Fetch profiles for these users
26	      const userIds = [...new Set((sessionData as any[]).map((s: any) => s.user_id).filter(Boolean))];
27	      const { data: profiles } = await supabase
28	        .from('profiles')
29	        .select('user_id, nome, username')
30	        .in('user_id', userIds);
31	
32	      const profileMap: Record<string, any> = {};
33	      (profiles || []).forEach((p: any) => {
34	        profileMap[p.user_id] = p;
35	      });
36	
37	      // Deduplicate by user_id: group sessions, keep most recent, collect all routes
38	      const byUser = new Map<string, any>();
39	      (sessionData as any[]).forEach((s: any) => {
40	        const existing = byUser.get(s.user_id);
41	        if (!existing) {
42	          byUser.set(s.user_id, {
43	            ...s,
44	            routes: [s.current_route].filter(Boolean),
45	            session_count: 1,
46	          });
47	        } else {
48	          existing.session_count++;
49	          if (s.current_route && !existing.routes.includes(s.current_route)) {
50	            existing.routes.push(s.current_route);
51	          }
52	          // Keep most recent activity
53	          if (new Date(s.last_activity) > new Date(existing.last_activity)) {
54	            existing.last_activity = s.last_activity;
55	            existing.device_type = s.device_type;
56	            existing.current_route = s.current_route;
57	          }
58	        }
59	      });
60	
61	      return Array.from(byUser.values()).map((s: any) => ({
62	        ...s,
63	        profile: profileMap[s.user_id] || null,
64	      }));
65	    },
66	    refetchInterval: 10_000,
67	  });
68	
69	  // Realtime subscription for instant updates
70	  useEffect(() => {
71	    const channel = supabase
72	      .channel('admin-sessions-realtime')
73	      .on(
74	        'postgres_changes' as any,
75	        { event: '*', schema: 'public', table: 'user_sessions' },
76	        () => {
77	          queryClient.invalidateQueries({ queryKey: ['admin', 'online-sessions'] });
78	        }
79	      )
80	      .subscribe();
81	
82	    return () => {
83	      supabase.removeChannel(channel);
84	    };
85	  }, [queryClient]);
86	
87	  return sessions;
88	}
