/**
 * @module features/tv-dashboard/model/types
 *
 * Tipos de domínio do Dashboard de Crise (painel TV `/tv`).
 * Spec: `.harness/spec/dashboard-tv-crise/spec.md`.
 */

/**
 * Canal de origem do dado de venda de uma unidade.
 *
 * - `degust-live`: lojas integradas ao POS Degust (flash-vendas ao vivo).
 *   O conjunto de lojas vem da tabela `degust_stores` em runtime (hoje:
 *   Lago Sul, Águas Claras, BSB Shopping) — nunca hardcoded.
 * - `linx-lagged`: lojas no POS Linx sem integração live — usamos o último
 *   dia disponível em `historico_vendas` com selo "até DD/MM".
 * - `factory`: fábrica (sem venda; card de produção/expedição).
 */
export type TvSalesChannel = 'degust-live' | 'linx-lagged' | 'factory';

/** Estado RAG (red/amber/green) de um card de unidade. */
export type TvRagStatus = 'ok' | 'amber' | 'red';

/** Nível de frescor de um dado-fonte em relação ao intervalo esperado. */
export type TvFreshnessLevel = 'fresh' | 'stale' | 'very-stale';

/** Severidade de uma exceção exibida na faixa inferior. */
export type TvExceptionSeverity = 'red' | 'amber';

/** Tipo de exceção exibida na faixa inferior. */
export type TvExceptionKind =
  | 'stock-out'
  | 'stock-low'
  | 'no-movement'
  | 'stale-data';

/** Janela de funcionamento usada no pró-rata da meta (hora local 0-24). */
export interface TvBusinessHours {
  start: number;
  end: number;
}

/** Snapshot de vendas de uma unidade (live ou defasado). */
export interface TvSalesSnapshot {
  /** Valor vendido em R$ no dia de referência. */
  valor: number;
  /** Número de cupons/transações (null quando a fonte não informa). */
  cupons: number | null;
  /** Ticket médio em R$ (null quando a fonte não informa). */
  ticketMedio: number | null;
  /** Dia a que o dado se refere (YYYY-MM-DD). Para canal live = hoje. */
  dataReferencia: string;
  /** true quando o dado é ao vivo (flash-vendas); false = defasado. */
  isLive: boolean;
  /** Caixa aberto agora (apenas canal live; null quando não se aplica). */
  caixaAberto: boolean | null;
  /** Timestamp informado pela fonte da última atualização (ISO, ou null). */
  atualizadoEm: string | null;
}

/** Contadores de alerta de estoque de uma unidade (apenas produtos ativos). */
export interface TvStockAlertSummary {
  /** Itens com quantidade <= 0 e mínimo definido (> 0). */
  zerados: number;
  /** Itens com 0 < quantidade < mínimo. */
  abaixoMinimo: number;
}

/** Item de estoque em alerta (detalhe usado na faixa de exceções). */
export interface TvStockAlertItem {
  produtoNome: string;
  quantidade: number;
  quantidadeMinima: number;
  /** true = zerado (vermelho); false = abaixo do mínimo (âmbar). */
  zerado: boolean;
}

/** Heartbeat de movimentações de estoque de uma unidade no dia. */
export interface TvMovementSummary {
  /** Contagem de movimentações tipo `entrada` hoje. */
  entradas: number;
  /** Contagem de movimentações tipo `saida` hoje. */
  saidas: number;
  /** Timestamp ISO da última movimentação ("última bipagem"), ou null. */
  ultimaBipagem: string | null;
}

/** Dados de um card de loja no grid. */
export interface TvStoreData {
  lojaId: number;
  nome: string;
  channel: TvSalesChannel;
  /** Vendas do dia de referência (null quando não há dado disponível). */
  vendas: TvSalesSnapshot | null;
  /** Meta do dia da semana de referência (`metas_vendas`), ou null. */
  metaDia: number | null;
  /**
   * % da meta. Canal live = pró-rata da janela de funcionamento;
   * canal defasado = % do dia COMPLETO de referência (dia já encerrado).
   * null quando não há meta cadastrada ou fora da janela.
   */
  pctMeta: number | null;
  /** Delta % vs MESMO DIA da semana anterior (nunca "ontem"), ou null. */
  deltaSemana: number | null;
  estoque: TvStockAlertSummary;
  movimentacao: TvMovementSummary;
  rag: TvRagStatus;
  /** Motivos legíveis (pt-BR) que levaram ao estado RAG. */
  ragReasons: string[];
}

/** Produção agregada da fábrica num dia. */
export interface TvFactoryProduction {
  /** Dia a que a produção se refere (YYYY-MM-DD — último dia com registro). */
  dataReferencia: string;
  /** Quantidade de produtos distintos produzidos. */
  itens: number;
  /** Soma das quantidades produzidas. */
  totalUnidades: number;
}

/** Dados do card diferenciado da fábrica. */
export interface TvFactoryData {
  lojaId: number;
  nome: string;
  /** Produção do dia (`daily_production` com loja_id NULL), ou null. */
  producao: TvFactoryProduction | null;
  /** Expedições = movimentações da fábrica hoje (saídas para lojas). */
  expedicoes: TvMovementSummary;
  estoque: TvStockAlertSummary;
  rag: TvRagStatus;
  ragReasons: string[];
}

/** Uma linha da faixa de exceções. */
export interface TvException {
  /** Id estável para keys de render (ex.: `stock-out:4:BROWNIE`). */
  id: string;
  kind: TvExceptionKind;
  severity: TvExceptionSeverity;
  lojaId: number | null;
  lojaNome: string | null;
  /** Mensagem pronta para exibição (pt-BR). */
  message: string;
  produtoNome?: string;
  quantidade?: number;
  quantidadeMinima?: number;
}

/** Faixa de exceções já ordenada (vermelho > âmbar) e limitada. */
export interface TvExceptionsResult {
  items: TvException[];
  /** Quantas exceções ficaram de fora do limite (para "+N itens"). */
  overflowCount: number;
  /** Total de exceções antes do corte. */
  totalCount: number;
}

/** Resumo da rede para o hero. */
export interface TvNetworkSummary {
  /**
   * Vendas de HOJE em R$ — soma apenas das lojas cujo dado é de hoje
   * (canal live). Lojas defasadas NÃO entram para não misturar dias.
   */
  vendasHoje: number;
  /** Soma das metas do dia das lojas que contribuem em `vendasHoje`. */
  metaDia: number | null;
  /** % da meta pró-rata da rede (mesma regra do card de loja live). */
  pctMetaProRata: number | null;
  /** Delta % vs mesmo dia da semana passada (lojas live), ou null. */
  deltaSemana: number | null;
  /** Total de exceções vermelhas na rede (sem cap de exibição). */
  alertasCriticos: number;
  /** Quantidade de lojas com venda ao vivo. */
  lojasLive: number;
  /** Quantidade de lojas com dado defasado. */
  lojasDefasadas: number;
}

/** Frescor de um dado-fonte. */
export interface TvSourceFreshness {
  /** Última atualização bem-sucedida (ISO), ou null se nunca carregou. */
  updatedAt: string | null;
  level: TvFreshnessLevel;
  /** Intervalo esperado de atualização (ms) usado na classificação. */
  expectedIntervalMs: number;
}

/** Freshness consolidado dos dados exibidos na TV. */
export interface TvFreshness {
  /** Vendas live (polling 60s na edge `degust-pos-financial`). */
  vendasLive: TvSourceFreshness;
  /** Estoque/alertas (polling 5min + Realtime). */
  estoque: TvSourceFreshness;
  /** Momento em que o snapshot foi montado (ISO). */
  geradoEm: string;
}

/**
 * @module features/tv-dashboard/model/tvMath
 *
 * Funções PURAS do Dashboard de Crise (painel TV): pró-rata de meta,
 * delta semanal, classificação RAG, formatação compacta de moeda,
 * staleness e agregações determinísticas usadas pelo hook de dados.
 *
 * Tudo aqui é livre de I/O e testável em isolamento (`tvMath.test.ts`).
 */

import type {
  TvBusinessHours,
  TvException,
  TvExceptionsResult,
  TvFreshnessLevel,
  TvRagStatus,
  TvStockAlertItem,
} from './types';

// ─────────────────────────────────────────────────────────────────────────────
// Constantes de negócio
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Janela de funcionamento das lojas usada no pró-rata da meta (hora local).
 * AJUSTÁVEL: se o horário comercial mudar, basta alterar aqui — todos os
 * cálculos de pró-rata e de "sem movimentação" derivam desta constante.
 */
export const TV_BUSINESS_HOURS: TvBusinessHours = { start: 9, end: 21 };

/** Horas sem movimentação (dentro da janela) que tornam a loja âmbar. */
export const NO_MOVEMENT_THRESHOLD_HOURS = 3;

/** % do esperado pró-rata abaixo do qual a venda live torna a loja vermelha. */
export const LIVE_SALES_RED_THRESHOLD_PCT = 50;

/** Máximo de linhas exibidas na faixa de exceções. */
export const TV_EXCEPTIONS_LIMIT = 7;

// ─────────────────────────────────────────────────────────────────────────────
// Datas (helpers locais, sem dependência de timezone UTC)
// ─────────────────────────────────────────────────────────────────────────────

/** Formata uma data como YYYY-MM-DD no fuso LOCAL (não UTC). */
export function toIsoDateLocal(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

/** Faz parse de YYYY-MM-DD como data LOCAL (evita shift de fuso do `new Date(iso)`). */
export function parseIsoDateLocal(iso: string): Date {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(y, (m ?? 1) - 1, d ?? 1);
}

/** Soma `days` dias a uma data, retornando nova instância. */
export function addDays(d: Date, days: number): Date {
  const out = new Date(d);
  out.setDate(out.getDate() + days);
  return out;
}

/** Rótulo de defasagem "até DD/MM" para dado que não é de hoje. */
export function formatLaggedDateLabel(isoDate: string): string {
  const d = parseIsoDateLocal(isoDate);
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  return `até ${dd}/${mm}`;
}

// ─────────────────────────────────────────────────────────────────────────────
// Pró-rata da meta
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Fração linear do dia comercial já decorrida em `now`.
 *
 * - Antes da abertura → 0 (não há venda esperada ainda).
 * - Depois do fechamento → 1 (meta integral esperada).
 * - Dentro da janela → interpolação linear simples (pró-rata).
 */
export function businessDayFraction(
  now: Date,
  hours: TvBusinessHours = TV_BUSINESS_HOURS,
): number {
  const { start, end } = hours;
  if (end <= start) {
    // Janela inválida — fail fast com comportamento seguro (sem divisão por 0)
    return now.getHours() >= end ? 1 : 0;
  }
  const h = now.getHours() + now.getMinutes() / 60 + now.getSeconds() / 3600;
  if (h <= start) return 0;
  if (h >= end) return 1;
  return (h - start) / (end - start);
}

/**
 * % da meta pró-rata: vendido / (meta diária × fração da janela decorrida).
 *
 * Retorna null quando não dá para calcular com honestidade:
 * - meta ausente/zerada (sem referência), ou
 * - antes da janela de funcionamento (esperado = 0; divisão sem sentido).
 */
export function pctOfProRataTarget(
  sold: number,
  dailyTarget: number | null | undefined,
  now: Date,
  hours: TvBusinessHours = TV_BUSINESS_HOURS,
): number | null {
  if (dailyTarget == null || dailyTarget <= 0) return null;
  const fraction = businessDayFraction(now, hours);
  if (fraction <= 0) return null;
  return (sold / (dailyTarget * fraction)) * 100;
}

/**
 * % da meta de um dia COMPLETO (sem pró-rata) — usado para canal defasado,
 * cujo dia de referência já encerrou.
 */
export function pctOfFullDayTarget(
  sold: number,
  dailyTarget: number | null | undefined,
): number | null {
  if (dailyTarget == null || dailyTarget <= 0) return null;
  return (sold / dailyTarget) * 100;
}

// ─────────────────────────────────────────────────────────────────────────────
// Delta semanal
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Delta % vs MESMO DIA da semana anterior (nunca "ontem" — spec).
 * Retorna null quando a base de comparação é ausente ou <= 0.
 */
export function weekOverWeekDelta(
  current: number,
  lastWeek: number | null | undefined,
): number | null {
  if (lastWeek == null || lastWeek <= 0) return null;
  return ((current - lastWeek) / lastWeek) * 100;
}

// ─────────────────────────────────────────────────────────────────────────────
// RAG da loja
// ─────────────────────────────────────────────────────────────────────────────

/** Entrada da classificação RAG de uma unidade. */
export interface StoreRagInput {
  /** Itens zerados em alerta (quantidade <= 0 com mínimo definido). */
  stockOutCount: number;
  /** Itens abaixo do mínimo (0 < quantidade < mínimo). */
  stockLowCount: number;
  /** % da meta pró-rata (apenas canal live; null = não avaliar). */
  pctMetaProRata: number | null;
  /** true quando a unidade tem venda ao vivo (canal Degust). */
  isLiveChannel: boolean;
  /** Última movimentação de estoque (ISO/Date), ou null se nenhuma hoje. */
  lastMovementAt: Date | string | null;
  /** Instante da avaliação. */
  now: Date;
  hours?: TvBusinessHours;
}

/**
 * Horas sem movimentação consideradas DENTRO da janela de funcionamento.
 *
 * - Fora da janela (antes de abrir / depois de fechar) retorna null —
 *   não faz sentido alertar madrugada sem bipagem.
 * - A referência é clampada ao início da janela de hoje: se a última
 *   movimentação foi ontem, o "relógio" só começa a contar na abertura.
 */
export function hoursWithoutMovementInWindow(
  lastMovementAt: Date | string | null,
  now: Date,
  hours: TvBusinessHours = TV_BUSINESS_HOURS,
): number | null {
  const fraction = businessDayFraction(now, hours);
  if (fraction <= 0 || fraction >= 1) return null;
  const windowStart = new Date(now);
  windowStart.setHours(hours.start, 0, 0, 0);
  const last = lastMovementAt
    ? new Date(lastMovementAt).getTime()
    : Number.NEGATIVE_INFINITY;
  const ref = Math.max(last, windowStart.getTime());
  return (now.getTime() - ref) / 3_600_000;
}

/**
 * Classificação RAG de uma unidade (management-by-exception).
 *
 * Regras (ordem de precedência):
 * - VERMELHO: existe item zerado em alerta (`stockOutCount > 0`) OU a venda
 *   live está abaixo de {@link LIVE_SALES_RED_THRESHOLD_PCT}% do esperado
 *   pró-rata (somente canal live e quando há meta → pct != null).
 * - ÂMBAR: existem itens abaixo do mínimo (`stockLowCount > 0`) OU a unidade
 *   está sem movimentação há mais de {@link NO_MOVEMENT_THRESHOLD_HOURS}h
 *   dentro da janela de funcionamento.
 * - OK: nenhum desvio — tela calma, sem cor.
 */
export function classifyStoreRag(input: StoreRagInput): {
  status: TvRagStatus;
  reasons: string[];
} {
  const hours = input.hours ?? TV_BUSINESS_HOURS;
  const reasons: string[] = [];

  // ── Vermelho ──
  if (input.stockOutCount > 0) {
    reasons.push(
      `${input.stockOutCount} ${input.stockOutCount === 1 ? 'item zerado' : 'itens zerados'} em alerta`,
    );
  }
  if (
    input.isLiveChannel &&
    input.pctMetaProRata !== null &&
    input.pctMetaProRata < LIVE_SALES_RED_THRESHOLD_PCT
  ) {
    reasons.push(
      `venda ao vivo em ${Math.round(input.pctMetaProRata)}% do esperado pró-rata`,
    );
  }
  if (reasons.length > 0) return { status: 'red', reasons };

  // ── Âmbar ──
  if (input.stockLowCount > 0) {
    reasons.push(
      `${input.stockLowCount} ${input.stockLowCount === 1 ? 'item abaixo' : 'itens abaixo'} do mínimo`,
    );
  }
  const gapHours = hoursWithoutMovementInWindow(
    input.lastMovementAt,
    input.now,
    hours,
  );
  if (gapHours !== null && gapHours > NO_MOVEMENT_THRESHOLD_HOURS) {
    reasons.push(`sem movimentação há ${Math.floor(gapHours)}h`);
  }
  if (reasons.length > 0) return { status: 'amber', reasons };

  return { status: 'ok', reasons: [] };
}

// ─────────────────────────────────────────────────────────────────────────────
// Formatação compacta de moeda (tipografia de TV: "R$ 12,4k")
// ─────────────────────────────────────────────────────────────────────────────

function trimOneDecimal(v: number): string {
  const rounded = Math.round(v * 10) / 10;
  return rounded.toLocaleString('pt-BR', {
    minimumFractionDigits: 0,
    maximumFractionDigits: 1,
  });
}

/**
 * Formata um valor em BRL compacto para leitura a 3-5 metros:
 * 950 → "R$ 950" · 12.400 → "R$ 12,4k" · 1.250.000 → "R$ 1,3M".
 * Valores negativos preservam o sinal ("-R$ 1,2k").
 */
export function formatCompactBRL(value: number): string {
  const sign = value < 0 ? '-' : '';
  const abs = Math.abs(value);
  // Bump pra M quando o arredondamento em k chegaria a 1000k
  if (abs >= 1_000_000 || (abs >= 1_000 && Math.round(abs / 100) >= 10_000)) {
    return `${sign}R$ ${trimOneDecimal(abs / 1_000_000)}M`;
  }
  if (abs >= 1_000) {
    return `${sign}R$ ${trimOneDecimal(abs / 1_000)}k`;
  }
  return `${sign}R$ ${Math.round(abs).toLocaleString('pt-BR')}`;
}

// ─────────────────────────────────────────────────────────────────────────────
// Staleness
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Classifica o frescor de um dado-fonte dado o intervalo esperado:
 * - `fresh`: idade < 2× intervalo esperado (tolerância de um ciclo perdido).
 * - `stale`: idade entre 2× e 6× (âmbar na UI, conforme spec).
 * - `very-stale`: idade >= 6× o intervalo, timestamp inválido ou ausente.
 */
export function classifyStaleness(
  lastUpdatedAt: Date | string | number | null | undefined,
  expectedIntervalMs: number,
  now: Date,
): TvFreshnessLevel {
  if (lastUpdatedAt == null) return 'very-stale';
  const ts = new Date(lastUpdatedAt).getTime();
  if (!Number.isFinite(ts) || ts <= 0) return 'very-stale';
  const age = now.getTime() - ts;
  if (age < 2 * expectedIntervalMs) return 'fresh';
  if (age < 6 * expectedIntervalMs) return 'stale';
  return 'very-stale';
}

// ─────────────────────────────────────────────────────────────────────────────
// Exceções — ordenação e corte
// ─────────────────────────────────────────────────────────────────────────────

const SEVERITY_ORDER: Record<string, number> = { red: 0, amber: 1 };
const KIND_ORDER: Record<string, number> = {
  'stock-out': 0,
  'no-movement': 1,
  'stock-low': 2,
  'stale-data': 3,
};

/**
 * Ordena exceções por severidade (vermelho > âmbar), depois por tipo
 * (falta total > sem movimentação > abaixo do mínimo > dado stale) e por
 * mensagem (estável), limitando a `limit` linhas com contagem do excedente.
 */
export function sortAndLimitExceptions(
  exceptions: TvException[],
  limit: number = TV_EXCEPTIONS_LIMIT,
): TvExceptionsResult {
  const sorted = [...exceptions].sort((a, b) => {
    const sev = (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9);
    if (sev !== 0) return sev;
    const kind = (KIND_ORDER[a.kind] ?? 9) - (KIND_ORDER[b.kind] ?? 9);
    if (kind !== 0) return kind;
    return a.message.localeCompare(b.message, 'pt-BR');
  });
  return {
    items: sorted.slice(0, limit),
    overflowCount: Math.max(0, sorted.length - limit),
    totalCount: sorted.length,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Agregações determinísticas usadas pelo hook (puras, testáveis)
// ─────────────────────────────────────────────────────────────────────────────

/** Linha mínima de `movimentacoes` necessária à agregação. */
export interface MovementRow {
  loja_id: number | null;
  tipo_movimentacao: string;
  data_movimentacao: string | null;
}

/** Resultado por loja da agregação de movimentações do dia. */
export interface MovementAggregate {
  entradas: number;
  saidas: number;
  ultimaBipagem: string | null;
}

/**
 * Agrega movimentações do dia por loja: contagem de entradas, saídas e
 * timestamp da última movimentação ("última bipagem"). Linhas sem loja
 * são ignoradas.
 */
export function aggregateMovements(
  rows: MovementRow[],
): Map<number, MovementAggregate> {
  const out = new Map<number, MovementAggregate>();
  for (const row of rows) {
    if (row.loja_id == null) continue;
    let agg = out.get(row.loja_id);
    if (!agg) {
      agg = { entradas: 0, saidas: 0, ultimaBipagem: null };
      out.set(row.loja_id, agg);
    }
    if (row.tipo_movimentacao === 'entrada') agg.entradas += 1;
    else if (row.tipo_movimentacao === 'saida') agg.saidas += 1;
    if (
      row.data_movimentacao &&
      (agg.ultimaBipagem === null || row.data_movimentacao > agg.ultimaBipagem)
    ) {
      agg.ultimaBipagem = row.data_movimentacao;
    }
  }
  return out;
}

/** Linha mínima de `estoque` (com nome do produto ativo já joinado). */
export interface StockRow {
  loja_id: number | null;
  quantidade_atual: number | null;
  quantidade_minima: number | null;
  produtoNome: string;
}

/** Detalhe de alertas de estoque por loja. */
export interface StockDetail {
  zerados: number;
  abaixoMinimo: number;
  itens: TvStockAlertItem[];
}

/**
 * Classifica linhas de estoque em alertas por loja (apenas produtos ATIVOS
 * devem chegar aqui — o JOIN com `produtos_master.ativo = true` é feito na
 * query). Regras (critério existente do projeto, sem schema novo):
 * - zerado (vermelho): quantidade <= 0 com mínimo definido (> 0);
 * - abaixo do mínimo (âmbar): 0 < quantidade < mínimo.
 */
export function buildStockSummary(rows: StockRow[]): Map<number, StockDetail> {
  const out = new Map<number, StockDetail>();
  for (const row of rows) {
    if (row.loja_id == null) continue;
    const min = row.quantidade_minima ?? 0;
    if (min <= 0) continue; // sem mínimo definido → sem alerta
    const qty = row.quantidade_atual ?? 0;
    if (qty >= min) continue; // dentro do normal
    let detail = out.get(row.loja_id);
    if (!detail) {
      detail = { zerados: 0, abaixoMinimo: 0, itens: [] };
      out.set(row.loja_id, detail);
    }
    const zerado = qty <= 0;
    if (zerado) detail.zerados += 1;
    else detail.abaixoMinimo += 1;
    detail.itens.push({
      produtoNome: row.produtoNome,
      quantidade: qty,
      quantidadeMinima: min,
      zerado,
    });
  }
  return out;
}

/**
 * Constrói as exceções de estoque (item × loja) a partir do detalhe por loja.
 * Itens zerados viram exceção vermelha; abaixo do mínimo, âmbar.
 */
export function buildStockExceptions(
  detailByLoja: Map<number, StockDetail>,
  lojaNomeById: Map<number, string>,
): TvException[] {
  const out: TvException[] = [];
  for (const [lojaId, detail] of detailByLoja) {
    const lojaNome = lojaNomeById.get(lojaId) ?? `Loja ${lojaId}`;
    for (const item of detail.itens) {
      out.push({
        id: `${item.zerado ? 'stock-out' : 'stock-low'}:${lojaId}:${item.produtoNome}`,
        kind: item.zerado ? 'stock-out' : 'stock-low',
        severity: item.zerado ? 'red' : 'amber',
        lojaId,
        lojaNome,
        message: item.zerado
          ? `${item.produtoNome} zerado — ${lojaNome}`
          : `${item.produtoNome} abaixo do mínimo (${item.quantidade}/${item.quantidadeMinima}) — ${lojaNome}`,
        produtoNome: item.produtoNome,
        quantidade: item.quantidade,
        quantidadeMinima: item.quantidadeMinima,
      });
    }
  }
  return out;
}

/** Linha de venda live normalizada (resposta da edge `degust-pos-financial`). */
export interface FlashRow {
  loja_id: number;
  nome_loja: string;
  total_vendas: number;
  total_cupons: number;
  ticket_medio: number;
  caixa_aberto: boolean;
  ultima_atualizacao: string | null;
}

/**
 * Corrige o `loja_id` das linhas de flash-vendas.
 *
 * LANDMINE conhecida: a edge function `degust-pos-financial` (deployada)
 * só mapeia os códigos Degust 1→4 e 2→5; códigos não mapeados passam CRUS
 * (ex.: BSB Shopping = código Degust 3 chega como `loja_id: 3`, colidindo
 * com Asa Norte). Aqui remapeamos usando a tabela `degust_stores`
 * (degust_loja_codigo → loja_id), que é a fonte de verdade em runtime.
 *
 * - Linha cujo loja_id já é uma loja Degust conhecida → mantém.
 * - Linha cujo loja_id corresponde a um código Degust → remapeia.
 * - Caso contrário → descarta (não corromper outra loja).
 */
export function remapFlashLojaIds(
  rows: FlashRow[],
  degustCodeToLoja: ReadonlyMap<number, number>,
  knownDegustLojaIds: ReadonlySet<number>,
): FlashRow[] {
  const out: FlashRow[] = [];
  for (const row of rows) {
    if (knownDegustLojaIds.has(row.loja_id)) {
      out.push(row);
      continue;
    }
    const mapped = degustCodeToLoja.get(row.loja_id);
    if (mapped != null) {
      out.push({ ...row, loja_id: mapped });
    }
    // não mapeável → descartado de propósito (ver TSDoc)
  }
  return out;
}

/** Linha mínima de `degust_vendas_diarias` para o top produtos. */
export interface DailyProductRow {
  degust_nome: string;
  quantidade: number | null;
  valor_total: number | null;
}

/** Produto agregado do dia (rede). */
export interface TvTopProduct {
  nome: string;
  quantidade: number;
  valor: number;
}

/**
 * Top N produtos do dia da rede, agregando `degust_vendas_diarias` por nome.
 * Ranking por quantidade vendida (desempate por valor).
 */
export function topProductsFromDaily(
  rows: DailyProductRow[],
  n = 5,
): TvTopProduct[] {
  const byName = new Map<string, TvTopProduct>();
  for (const row of rows) {
    let agg = byName.get(row.degust_nome);
    if (!agg) {
      agg = { nome: row.degust_nome, quantidade: 0, valor: 0 };
      byName.set(row.degust_nome, agg);
    }
    agg.quantidade += row.quantidade ?? 0;
    agg.valor += row.valor_total ?? 0;
  }
  return [...byName.values()]
    .sort((a, b) => b.quantidade - a.quantidade || b.valor - a.valor)
    .slice(0, n);
}

/**
 * @module features/tv-dashboard/model/useTvDashboardData
 *
 * Hook principal do Dashboard de Crise (painel TV `/tv`).
 *
 * Paraleliza as fontes de dados via React Query:
 * - vendas live (edge `degust-pos-financial`/flash-vendas) — polling 60s;
 * - vendas defasadas Linx (`historico_vendas`, último dia disponível);
 * - comparativo vs MESMO DIA da semana passada (`degust_vendas_diarias` /
 *   `historico_vendas`);
 * - metas por loja × dia da semana (`metas_vendas`) com pró-rata da janela;
 * - alertas de estoque (`estoque` × `produtos_master.ativo = true`);
 * - heartbeat de movimentações (`movimentacoes` de hoje);
 * - produção da fábrica (`daily_production` com loja_id NULL);
 * - top 5 produtos do dia da rede (`degust_vendas_diarias`).
 *
 * Nenhum `loja_id` é hardcoded: os canais são derivados em runtime de
 * `lojas` + `degust_stores` (Degust = live; demais lojas ativas = Linx
 * defasado; tipo "Fabrica" = card de fábrica).
 */

import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import type {
  TvException,
  TvFactoryData,
  TvFactoryProduction,
  TvFreshness,
  TvMovementSummary,
  TvNetworkSummary,
  TvSalesChannel,
  TvSalesSnapshot,
  TvStoreData,
  TvExceptionsResult,
} from './types';
import {
  addDays,
  aggregateMovements,
  buildStockExceptions,
  buildStockSummary,
  classifyStaleness,
  classifyStoreRag,
  parseIsoDateLocal,
  pctOfFullDayTarget,
  pctOfProRataTarget,
  remapFlashLojaIds,
  sortAndLimitExceptions,
  toIsoDateLocal,
  topProductsFromDaily,
  weekOverWeekDelta,
  type FlashRow,
  type MovementAggregate,
  type StockDetail,
  type StockRow,
  type TvTopProduct,
} from './tvMath';

// ─────────────────────────────────────────────────────────────────────────────
// Query keys + intervalos (exportados para o useTvRealtime invalidar)
// ─────────────────────────────────────────────────────────────────────────────

/** Query keys do painel TV — usar SEMPRE estas referências para invalidar. */
export const tvDashboardKeys = {
  all: ['tv-dashboard'] as const,
  context: () => [...tvDashboardKeys.all, 'context'] as const,
  liveSales: () => [...tvDashboardKeys.all, 'live-sales'] as const,
  laggedSales: () => [...tvDashboardKeys.all, 'lagged-sales'] as const,
  lastWeekSales: () => [...tvDashboardKeys.all, 'last-week-sales'] as const,
  metas: () => [...tvDashboardKeys.all, 'metas'] as const,
  stock: () => [...tvDashboardKeys.all, 'stock'] as const,
  movements: () => [...tvDashboardKeys.all, 'movements'] as const,
  factoryProduction: () => [...tvDashboardKeys.all, 'factory-production'] as const,
  topProducts: () => [...tvDashboardKeys.all, 'top-products'] as const,
};

/** Intervalos de atualização (ms) por classe de dado. */
export const TV_QUERY_INTERVALS = {
  /** Vendas live: polling 60s (acceptance: atualização <= 60s). */
  liveMs: 60_000,
  /** Estoque/metas/movimentações/produção: 5min (+ Realtime invalida antes). */
  slowMs: 300_000,
} as const;

// ─────────────────────────────────────────────────────────────────────────────
// Contexto: lojas + canais (derivados em runtime, sem hardcode de loja_id)
// ─────────────────────────────────────────────────────────────────────────────

interface TvLoja {
  id: number;
  nome: string;
  tipo: string | null;
}

interface TvContext {
  lojas: TvLoja[];
  /** Lojas com venda live (existem em `degust_stores`). */
  degustLojaIds: Set<number>;
  /** Mapa código Degust → loja_id (corrige pass-through da edge function). */
  degustCodeToLoja: Map<number, number>;
  /** Lojas ativas de venda SEM integração live (canal Linx, defasado). */
  linxLojaIds: number[];
  /** Loja tipo fábrica (tipo "Fabrica", case-insensitive), ou null. */
  factoryLojaId: number | null;
}

function isFactoryTipo(tipo: string | null): boolean {
  // Valores reais na tabela divergem em caixa ("Fabrica" / "loja" / "Loja")
  return (tipo ?? '').toLowerCase().startsWith('fabrica') || (tipo ?? '').toLowerCase().startsWith('fábrica');
}

async function fetchTvContext(): Promise<TvContext> {
  const [lojasRes, degustRes] = await Promise.all([
    supabase
      .from('lojas')
      .select('id, nome, tipo')
      .eq('ativo', true)
      .order('id'),
    supabase.from('degust_stores').select('loja_id, degust_loja_codigo'),
  ]);
  if (lojasRes.error) throw lojasRes.error;
  if (degustRes.error) throw degustRes.error;

  const lojas: TvLoja[] = lojasRes.data ?? [];
  const degustLojaIds = new Set<number>();
  const degustCodeToLoja = new Map<number, number>();
  for (const row of degustRes.data ?? []) {
    degustLojaIds.add(row.loja_id);
    degustCodeToLoja.set(row.degust_loja_codigo, row.loja_id);
  }

  const factoryLojaId = lojas.find((l) => isFactoryTipo(l.tipo))?.id ?? null;
  const linxLojaIds = lojas
    .filter((l) => !isFactoryTipo(l.tipo) && !degustLojaIds.has(l.id))
    .map((l) => l.id);

  return { lojas, degustLojaIds, degustCodeToLoja, linxLojaIds, factoryLojaId };
}

