/** Contrato da edge `degust-pos-financial` (campos usados pelo painel). */
interface DegustPosFinancialResponse {
  flash?: Array<{
    loja_id: number;
    nome_loja: string;
    total_vendas: number;
    total_cupons: number;
    ticket_medio: number;
    qtd_produtos: number;
    caixa_aberto: boolean;
    ultima_atualizacao: string | null;
  }>;
}

async function fetchLiveSales(ctx: TvContext): Promise<FlashRow[]> {
  const today = toIsoDateLocal(new Date());
  const { data, error } = await supabase.functions.invoke<DegustPosFinancialResponse>(
    'degust-pos-financial',
    { body: { startDate: today, endDate: today } },
  );
  if (error) throw error;
  const flash: FlashRow[] = (data?.flash ?? []).map((f) => ({
    loja_id: f.loja_id,
    nome_loja: f.nome_loja,
    total_vendas: f.total_vendas,
    total_cupons: f.total_cupons,
    ticket_medio: f.ticket_medio,
    caixa_aberto: f.caixa_aberto,
    ultima_atualizacao: f.ultima_atualizacao,
  }));
  return remapFlashLojaIds(flash, ctx.degustCodeToLoja, ctx.degustLojaIds);
}

// ─────────────────────────────────────────────────────────────────────────────
// Vendas defasadas (Linx via historico_vendas — último dia disponível)
// ─────────────────────────────────────────────────────────────────────────────

interface LaggedSales {
  lojaId: number;
  /** Último dia com venda registrada (YYYY-MM-DD). */
  dataReferencia: string;
  valor: number;
  quantidade: number;
  /** Valor do MESMO DIA da semana anterior ao dia de referência, ou null. */
  valorSemanaAnterior: number | null;
}

async function fetchLaggedStore(lojaId: number): Promise<LaggedSales | null> {
  // 1) Último dia com dado para a loja
  const { data: latest, error: latestErr } = await supabase
    .from('historico_vendas')
    .select('data')
    .eq('loja_id', lojaId)
    .order('data', { ascending: false })
    .limit(1);
  if (latestErr) throw latestErr;
  const refDate = latest?.[0]?.data;
  if (!refDate) return null;

  const prevDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -7));

  // 2) Vendas do dia de referência + mesmo dia da semana anterior
  const [curRes, prevRes] = await Promise.all([
    supabase
      .from('historico_vendas')
      .select('valor_total, quantidade')
      .eq('loja_id', lojaId)
      .eq('data', refDate)
      .limit(2000),
    supabase
      .from('historico_vendas')
      .select('valor_total')
      .eq('loja_id', lojaId)
      .eq('data', prevDate)
      .limit(2000),
  ]);
  if (curRes.error) throw curRes.error;
  if (prevRes.error) throw prevRes.error;

  const valor = (curRes.data ?? []).reduce((s, r) => s + (r.valor_total ?? 0), 0);
  const quantidade = (curRes.data ?? []).reduce(
    (s, r) => s + (r.quantidade ?? 0),
    0,
  );
  const prevRows = prevRes.data ?? [];
  const valorSemanaAnterior =
    prevRows.length > 0
      ? prevRows.reduce((s, r) => s + (r.valor_total ?? 0), 0)
      : null;

  return { lojaId, dataReferencia: refDate, valor, quantidade, valorSemanaAnterior };
}

async function fetchLaggedSales(ctx: TvContext): Promise<LaggedSales[]> {
  const results = await Promise.all(ctx.linxLojaIds.map(fetchLaggedStore));
  return results.filter((r): r is LaggedSales => r !== null);
}

// ─────────────────────────────────────────────────────────────────────────────
// Comparativo Degust: mesmo dia da semana passada (degust_vendas_diarias)
// ─────────────────────────────────────────────────────────────────────────────

async function fetchDegustLastWeek(ctx: TvContext): Promise<Map<number, number>> {
  const lastWeekDate = toIsoDateLocal(addDays(new Date(), -7));
  const ids = [...ctx.degustLojaIds];
  const out = new Map<number, number>();
  if (ids.length === 0) return out;
  const { data, error } = await supabase
    .from('degust_vendas_diarias')
    .select('loja_id, valor_total')
    .eq('data', lastWeekDate)
    .in('loja_id', ids)
    .limit(5000);
  if (error) throw error;
  for (const row of data ?? []) {
    out.set(row.loja_id, (out.get(row.loja_id) ?? 0) + (row.valor_total ?? 0));
  }
  return out;
}

// ─────────────────────────────────────────────────────────────────────────────
// Metas (loja × dia da semana, convenção JS Date.getDay(): 0=domingo)
// ─────────────────────────────────────────────────────────────────────────────

async function fetchMetas(): Promise<Map<string, number>> {
  const { data, error } = await supabase
    .from('metas_vendas')
    .select('loja_id, dia_semana, valor_meta')
    .limit(1000);
  if (error) throw error;
  const out = new Map<string, number>();
  for (const row of data ?? []) {
    out.set(`${row.loja_id}:${row.dia_semana}`, row.valor_meta);
  }
  return out;
}

function metaFor(
  metas: Map<string, number> | undefined,
  lojaId: number,
  date: Date,
): number | null {
  if (!metas) return null;
  return metas.get(`${lojaId}:${date.getDay()}`) ?? null;
}

// ─────────────────────────────────────────────────────────────────────────────
// Estoque em alerta (JOIN com produtos ATIVOS — regra dura do projeto)
// ─────────────────────────────────────────────────────────────────────────────

async function fetchStockAlerts(): Promise<StockRow[]> {
  // PostgREST não compara coluna×coluna (quantidade_atual < quantidade_minima):
  // buscamos as linhas com mínimo definido e filtramos no cliente (~1.4k linhas).
  const { data, error } = await supabase
    .from('estoque')
    .select(
      'loja_id, quantidade_atual, quantidade_minima, produto_master:produtos_master!inner(nome, ativo)',
    )
    .eq('produto_master.ativo', true)
    .gt('quantidade_minima', 0)
    .or('oculto.is.null,oculto.eq.false')
    .limit(5000);
  if (error) throw error;
  return (data ?? []).map((row) => ({
    loja_id: row.loja_id,
    quantidade_atual: row.quantidade_atual,
    quantidade_minima: row.quantidade_minima,
    produtoNome: row.produto_master?.nome ?? '(sem nome)',
  }));
}

// ─────────────────────────────────────────────────────────────────────────────
// Movimentações de hoje (heartbeat por loja)
// ─────────────────────────────────────────────────────────────────────────────

async function fetchMovementsToday(): Promise<Map<number, MovementAggregate>> {
  const startOfDay = new Date();
  startOfDay.setHours(0, 0, 0, 0);
  const { data, error } = await supabase
    .from('movimentacoes')
    .select('loja_id, tipo_movimentacao, data_movimentacao')
    .gte('data_movimentacao', startOfDay.toISOString())
    .limit(10_000);
  if (error) throw error;
  return aggregateMovements(data ?? []);
}

// ─────────────────────────────────────────────────────────────────────────────
// Produção da fábrica (daily_production com loja_id NULL = fábrica)
// ─────────────────────────────────────────────────────────────────────────────

async function fetchFactoryProduction(): Promise<TvFactoryProduction | null> {
  const today = toIsoDateLocal(new Date());

  const loadDay = async (date: string) => {
    const { data, error } = await supabase
      .from('daily_production')
      .select('quantity')
      .is('loja_id', null)
      .eq('date', date)
      .limit(2000);
    if (error) throw error;
    return data ?? [];
  };

  let refDate = today;
  let rows = await loadDay(today);
  if (rows.length === 0) {
    // Sem produção registrada hoje → mostra o último dia disponível
    const { data: latest, error } = await supabase
      .from('daily_production')
      .select('date')
      .is('loja_id', null)
      .lte('date', today)
      .order('date', { ascending: false })
      .limit(1);
    if (error) throw error;
    const lastDate = latest?.[0]?.date;
    if (!lastDate) return null;
    refDate = lastDate;
    rows = await loadDay(lastDate);
  }

  return {
    dataReferencia: refDate,
    itens: rows.length,
    totalUnidades: rows.reduce((s, r) => s + (r.quantity ?? 0), 0),
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Top produtos do dia da rede (degust_vendas_diarias, dia mais recente)
// ─────────────────────────────────────────────────────────────────────────────

async function fetchTopProducts(ctx: TvContext): Promise<TvTopProduct[]> {
  const ids = [...ctx.degustLojaIds];
  if (ids.length === 0) return [];
  const { data: latest, error: latestErr } = await supabase
    .from('degust_vendas_diarias')
    .select('data')
    .in('loja_id', ids)
    .order('data', { ascending: false })
    .limit(1);
  if (latestErr) throw latestErr;
  const refDate = latest?.[0]?.data;
  if (!refDate) return [];

  const { data, error } = await supabase
    .from('degust_vendas_diarias')
    .select('degust_nome, quantidade, valor_total')
    .eq('data', refDate)
    .in('loja_id', ids)
    .limit(5000);
  if (error) throw error;
  return topProductsFromDaily(data ?? [], 5);
}

// ─────────────────────────────────────────────────────────────────────────────
// Hook principal
// ─────────────────────────────────────────────────────────────────────────────

/** Retorno do {@link useTvDashboardData}. */
export interface TvDashboardData {
  network: TvNetworkSummary | null;
  stores: TvStoreData[];
  factory: TvFactoryData | null;
  exceptions: TvExceptionsResult;
  topProducts: TvTopProduct[];
  freshness: TvFreshness;
  /** true enquanto o contexto (lojas/canais) ainda não carregou. */
  isLoading: boolean;
  /** true quando o contexto falhou (painel não consegue montar). */
  isError: boolean;
}

const EMPTY_MOVEMENT: TvMovementSummary = {
  entradas: 0,
  saidas: 0,
  ultimaBipagem: null,
};

/**
 * Hook principal do painel TV. Paraleliza todas as fontes e devolve o
 * snapshot consolidado (`network`, `stores`, `factory`, `exceptions`,
 * `topProducts`, `freshness`). Vendas live re-buscam a cada 60s; o resto a
 * cada 5min (com invalidação antecipada via {@link useTvRealtime}).
 */
export function useTvDashboardData(): TvDashboardData {
  const ctxQuery = useQuery({
    queryKey: tvDashboardKeys.context(),
    queryFn: fetchTvContext,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });
  const ctx = ctxQuery.data;

  const liveQuery = useQuery({
    queryKey: tvDashboardKeys.liveSales(),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchLiveSales(ctx);
    },
    enabled: !!ctx,
    refetchInterval: TV_QUERY_INTERVALS.liveMs,
    staleTime: 30_000,
  });

  const laggedQuery = useQuery({
    queryKey: tvDashboardKeys.laggedSales(),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchLaggedSales(ctx);
    },
    enabled: !!ctx,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const lastWeekQuery = useQuery({
    queryKey: tvDashboardKeys.lastWeekSales(),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchDegustLastWeek(ctx);
    },
    enabled: !!ctx,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const metasQuery = useQuery({
    queryKey: tvDashboardKeys.metas(),
    queryFn: fetchMetas,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const stockQuery = useQuery({
    queryKey: tvDashboardKeys.stock(),
    queryFn: fetchStockAlerts,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const movementsQuery = useQuery({
    queryKey: tvDashboardKeys.movements(),
    queryFn: fetchMovementsToday,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const factoryQuery = useQuery({
    queryKey: tvDashboardKeys.factoryProduction(),
    queryFn: fetchFactoryProduction,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  const topQuery = useQuery({
    queryKey: tvDashboardKeys.topProducts(),
    queryFn: () => {
      if (!ctx) throw new Error('tv-dashboard: contexto ausente');
      return fetchTopProducts(ctx);
    },
    enabled: !!ctx,
    staleTime: TV_QUERY_INTERVALS.slowMs,
    refetchInterval: TV_QUERY_INTERVALS.slowMs,
  });

  return useMemo<TvDashboardData>(() => {
    const now = new Date();
    const todayIso = toIsoDateLocal(now);

    const stockDetail: Map<number, StockDetail> = buildStockSummary(
      stockQuery.data ?? [],
    );
    const movements = movementsQuery.data ?? new Map<number, MovementAggregate>();
    const flashByLoja = new Map<number, FlashRow>(
      (liveQuery.data ?? []).map((f) => [f.loja_id, f]),
    );
    const laggedByLoja = new Map<number, LaggedSales>(
      (laggedQuery.data ?? []).map((l) => [l.lojaId, l]),
    );
    const lastWeekByLoja = lastWeekQuery.data ?? new Map<number, number>();
    const lojaNomeById = new Map<number, string>(
      (ctx?.lojas ?? []).map((l) => [l.id, l.nome]),
    );

    // ── Cards de loja ──
    const stores: TvStoreData[] = (ctx?.lojas ?? [])
      .filter((l) => !isFactoryTipo(l.tipo))
      .map((loja) => {
        const channel: TvSalesChannel = ctx?.degustLojaIds.has(loja.id)
          ? 'degust-live'
          : 'linx-lagged';
        const stock = stockDetail.get(loja.id);
        const movement = movements.get(loja.id) ?? EMPTY_MOVEMENT;

        let vendas: TvSalesSnapshot | null = null;
        let metaDia: number | null = null;
        let pctMeta: number | null = null;
        let deltaSemana: number | null = null;

        if (channel === 'degust-live') {
          const flash = flashByLoja.get(loja.id);
          if (flash) {
            vendas = {
              valor: flash.total_vendas,
              cupons: flash.total_cupons,
              ticketMedio: flash.ticket_medio,
              dataReferencia: todayIso,
              isLive: true,
              caixaAberto: flash.caixa_aberto,
              atualizadoEm: flash.ultima_atualizacao,
            };
            metaDia = metaFor(metasQuery.data, loja.id, now);
            pctMeta = pctOfProRataTarget(flash.total_vendas, metaDia, now);
            deltaSemana = weekOverWeekDelta(
              flash.total_vendas,
              lastWeekByLoja.get(loja.id) ?? null,
            );
          }
        } else {
          const lagged = laggedByLoja.get(loja.id);
          if (lagged) {
            vendas = {
              valor: lagged.valor,
              cupons: null,
              ticketMedio: null,
              dataReferencia: lagged.dataReferencia,
              isLive: false,
              caixaAberto: null,
              atualizadoEm: null,
            };
            // Meta do dia da semana do DIA DE REFERÊNCIA (já encerrado → sem pró-rata)
            const refDate = parseIsoDateLocal(lagged.dataReferencia);
            metaDia = metaFor(metasQuery.data, loja.id, refDate);
            pctMeta = pctOfFullDayTarget(lagged.valor, metaDia);
            deltaSemana = weekOverWeekDelta(
              lagged.valor,
              lagged.valorSemanaAnterior,
            );
          }
        }

        const rag = classifyStoreRag({
          stockOutCount: stock?.zerados ?? 0,
          stockLowCount: stock?.abaixoMinimo ?? 0,
          pctMetaProRata: channel === 'degust-live' ? pctMeta : null,
          isLiveChannel: channel === 'degust-live',
          lastMovementAt: movement.ultimaBipagem,
          now,
        });

        return {
          lojaId: loja.id,
          nome: loja.nome,
          channel,
          vendas,
          metaDia,
          pctMeta,
          deltaSemana,
          estoque: {
            zerados: stock?.zerados ?? 0,
            abaixoMinimo: stock?.abaixoMinimo ?? 0,
          },
          movimentacao: movement,
          rag: rag.status,
          ragReasons: rag.reasons,
        };
      });

    // ── Card da fábrica ──
    let factory: TvFactoryData | null = null;
    if (ctx?.factoryLojaId != null) {
      const fid = ctx.factoryLojaId;
      const stock = stockDetail.get(fid);
      const movement = movements.get(fid) ?? EMPTY_MOVEMENT;
      const rag = classifyStoreRag({
        stockOutCount: stock?.zerados ?? 0,
        stockLowCount: stock?.abaixoMinimo ?? 0,
        pctMetaProRata: null,
        isLiveChannel: false,
        lastMovementAt: movement.ultimaBipagem,
        now,
      });
      factory = {
        lojaId: fid,
        nome: lojaNomeById.get(fid) ?? 'Fábrica',
        producao: factoryQuery.data ?? null,
        expedicoes: movement,
        estoque: {
          zerados: stock?.zerados ?? 0,
          abaixoMinimo: stock?.abaixoMinimo ?? 0,
        },
        rag: rag.status,
        ragReasons: rag.reasons,
      };
    }

    // ── Freshness ──
    const liveUpdatedAt =
      liveQuery.dataUpdatedAt > 0
        ? new Date(liveQuery.dataUpdatedAt).toISOString()
        : null;
    const stockUpdatedAt =
      stockQuery.dataUpdatedAt > 0
        ? new Date(stockQuery.dataUpdatedAt).toISOString()
        : null;
    const freshness: TvFreshness = {
      vendasLive: {
        updatedAt: liveUpdatedAt,
        level: classifyStaleness(liveUpdatedAt, TV_QUERY_INTERVALS.liveMs, now),
        expectedIntervalMs: TV_QUERY_INTERVALS.liveMs,
      },
      estoque: {
        updatedAt: stockUpdatedAt,
        level: classifyStaleness(stockUpdatedAt, TV_QUERY_INTERVALS.slowMs, now),
        expectedIntervalMs: TV_QUERY_INTERVALS.slowMs,
      },
      geradoEm: now.toISOString(),
    };

    // ── Exceções (vermelho > âmbar, máx 7 + excedente) ──
    const allExceptions: TvException[] = buildStockExceptions(
      stockDetail,
      lojaNomeById,
    );
    for (const store of stores) {
      const noMovement = store.ragReasons.find((r) =>
        r.startsWith('sem movimentação'),
      );
      if (noMovement) {
        allExceptions.push({
          id: `no-movement:${store.lojaId}`,
          kind: 'no-movement',
          severity: 'amber',
          lojaId: store.lojaId,
          lojaNome: store.nome,
          message: `${store.nome} ${noMovement} em horário comercial`,
        });
      }
    }
    if (freshness.vendasLive.level !== 'fresh' && (ctx?.degustLojaIds.size ?? 0) > 0) {
      allExceptions.push({
        id: 'stale-data:vendas-live',
        kind: 'stale-data',
        severity: 'amber',
        lojaId: null,
        lojaNome: null,
        message: liveUpdatedAt
          ? `Venda live sem atualização desde ${new Date(liveUpdatedAt).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`
          : 'Venda live ainda não carregou',
      });
    }
    const exceptions = sortAndLimitExceptions(allExceptions);

    // ── Hero (rede) ──
    // Soma apenas lojas cujo dado é de HOJE (live) — não misturar dias.
    const liveStores = stores.filter(
      (s) => s.vendas?.isLive && s.vendas.dataReferencia === todayIso,
    );
    const vendasHoje = liveStores.reduce((s, st) => s + (st.vendas?.valor ?? 0), 0);
    const metasHoje = liveStores
      .map((s) => s.metaDia)
      .filter((m): m is number => m != null && m > 0);
    const metaDia = metasHoje.length > 0 ? metasHoje.reduce((a, b) => a + b, 0) : null;
    const lastWeekTotal = liveStores.reduce(
      (s, st) => s + (lastWeekByLoja.get(st.lojaId) ?? 0),
      0,
    );
    const network: TvNetworkSummary | null = ctx
      ? {
          vendasHoje,
          metaDia,
          pctMetaProRata: pctOfProRataTarget(vendasHoje, metaDia, now),
          deltaSemana: weekOverWeekDelta(vendasHoje, lastWeekTotal > 0 ? lastWeekTotal : null),
          alertasCriticos: allExceptions.filter((e) => e.severity === 'red').length,
          lojasLive: liveStores.length,
          lojasDefasadas: stores.filter((s) => s.channel === 'linx-lagged').length,
        }
      : null;

    return {
      network,
      stores,
      factory,
      exceptions,
      topProducts: topQuery.data ?? [],
      freshness,
      isLoading: ctxQuery.isLoading,
      isError: ctxQuery.isError,
    };
  }, [
    ctx,
    ctxQuery.isLoading,
    ctxQuery.isError,
    liveQuery.data,
    liveQuery.dataUpdatedAt,
    laggedQuery.data,
    lastWeekQuery.data,
    metasQuery.data,
    stockQuery.data,
    stockQuery.dataUpdatedAt,
    movementsQuery.data,
    factoryQuery.data,
    topQuery.data,
  ]);
}

/**
 * @module features/tv-dashboard/model/useTvRealtime
 *
 * Assina canais Supabase Realtime nas tabelas `movimentacoes`, `estoque` e
 * `alertas_estoque` (mesmo padrão de `features/dashboard/useRealtimeUpdates`)
 * e invalida as query keys do painel TV para refletir mudanças antes do
 * próximo ciclo de polling.
 *
 * As invalidações são debounced (janela de 2s) para não estourar refetches
 * durante rajadas de bipagem (conferência de expedição gera dezenas de
 * INSERTs em sequência).
 */

import { useEffect, useRef } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { tvDashboardKeys } from './useTvDashboardData';

/** Janela de debounce das invalidações disparadas pelo Realtime (ms). */
const REALTIME_DEBOUNCE_MS = 2_000;

/**
 * Subscreve `postgres_changes` em movimentações/estoque/alertas e invalida
 * as queries relevantes do painel TV:
 * - `movimentacoes` → heartbeat de movimentações (+ expedições da fábrica);
 * - `estoque` / `alertas_estoque` → alertas de estoque (faixa de exceções).
 *
 * Remove os canais e cancela timers pendentes ao desmontar.
 */
export function useTvRealtime(): void {
  const queryClient = useQueryClient();
  // Timers por grupo de invalidação (debounce independente)
  const movementTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const stockTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    const invalidateMovements = () => {
      if (movementTimer.current) return; // já agendado nesta janela
      movementTimer.current = setTimeout(() => {
        movementTimer.current = null;
        queryClient.invalidateQueries({ queryKey: tvDashboardKeys.movements() });
      }, REALTIME_DEBOUNCE_MS);
    };

    const invalidateStock = () => {
      if (stockTimer.current) return;
      stockTimer.current = setTimeout(() => {
        stockTimer.current = null;
        queryClient.invalidateQueries({ queryKey: tvDashboardKeys.stock() });
      }, REALTIME_DEBOUNCE_MS);
    };

    const movementsChannel = supabase
      .channel('tv-movements-changes')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'movimentacoes' },
        invalidateMovements,
      )
      .subscribe();

    const stockChannel = supabase
      .channel('tv-stock-changes')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'estoque' },
        invalidateStock,
      )
      .subscribe();

    const alertsChannel = supabase
      .channel('tv-alerts-changes')
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'alertas_estoque' },
        invalidateStock,
      )
      .subscribe();

    return () => {
      if (movementTimer.current) clearTimeout(movementTimer.current);
      if (stockTimer.current) clearTimeout(stockTimer.current);
      movementTimer.current = null;
      stockTimer.current = null;
      supabase.removeChannel(movementsChannel);
      supabase.removeChannel(stockChannel);
      supabase.removeChannel(alertsChannel);
    };
  }, [queryClient]);
}

import { describe, it, expect } from 'vitest';
import {
  TV_BUSINESS_HOURS,
  NO_MOVEMENT_THRESHOLD_HOURS,
  aggregateMovements,
  buildStockExceptions,
  buildStockSummary,
  businessDayFraction,
  classifyStaleness,
  classifyStoreRag,
  formatCompactBRL,
  formatLaggedDateLabel,
  hoursWithoutMovementInWindow,
  parseIsoDateLocal,
  pctOfFullDayTarget,
  pctOfProRataTarget,
  remapFlashLojaIds,
  sortAndLimitExceptions,
  toIsoDateLocal,
  topProductsFromDaily,
  weekOverWeekDelta,
