// Datas locais determinísticas (sem dependência de fuso/UTC)
const at = (hour: number, minute = 0) => new Date(2026, 5, 4, hour, minute, 0); // qui 04/06/2026

describe('datas locais', () => {
  it('toIsoDateLocal formata no fuso local', () => {
    expect(toIsoDateLocal(new Date(2026, 0, 9))).toBe('2026-01-09');
  });

  it('parseIsoDateLocal não sofre shift de fuso', () => {
    const d = parseIsoDateLocal('2026-04-09');
    expect(d.getFullYear()).toBe(2026);
    expect(d.getMonth()).toBe(3);
    expect(d.getDate()).toBe(9);
  });

  it('formatLaggedDateLabel gera "até DD/MM"', () => {
    expect(formatLaggedDateLabel('2026-04-09')).toBe('até 09/04');
