describe('businessDayFraction', () => {
  it('retorna 0 antes da janela', () => {
    expect(businessDayFraction(at(7))).toBe(0);
    expect(businessDayFraction(at(TV_BUSINESS_HOURS.start))).toBe(0); // exatamente na abertura
  });

  it('retorna 1 depois da janela', () => {
    expect(businessDayFraction(at(21))).toBe(1);
    expect(businessDayFraction(at(23, 30))).toBe(1);
  });

  it('interpola linearmente dentro da janela (9-21)', () => {
    expect(businessDayFraction(at(15))).toBeCloseTo(0.5, 5); // metade do dia
    expect(businessDayFraction(at(12))).toBeCloseTo(0.25, 5);
    expect(businessDayFraction(at(12, 30))).toBeCloseTo(3.5 / 12, 5);
  });

  it('aceita janela customizada', () => {
    expect(businessDayFraction(at(11), { start: 10, end: 12 })).toBeCloseTo(0.5, 5);
  });

  it('janela inválida (end <= start) não divide por zero', () => {
    expect(businessDayFraction(at(8), { start: 10, end: 10 })).toBe(0);
    expect(businessDayFraction(at(12), { start: 10, end: 10 })).toBe(1);
  });
});

describe('pctOfProRataTarget', () => {
  it('calcula % do esperado pró-rata no meio do dia', () => {
    // Meta 1000, 15h = 50% do dia → esperado 500; vendido 400 → 80%
    expect(pctOfProRataTarget(400, 1000, at(15))).toBeCloseTo(80, 5);
  });

  it('depois do fechamento usa a meta integral', () => {
    expect(pctOfProRataTarget(900, 1000, at(22))).toBeCloseTo(90, 5);
  });

  it('antes da janela retorna null (esperado = 0)', () => {
    expect(pctOfProRataTarget(100, 1000, at(7))).toBeNull();
  });

  it('sem meta (null/0/negativa) retorna null', () => {
    expect(pctOfProRataTarget(100, null, at(15))).toBeNull();
    expect(pctOfProRataTarget(100, undefined, at(15))).toBeNull();
    expect(pctOfProRataTarget(100, 0, at(15))).toBeNull();
    expect(pctOfProRataTarget(100, -10, at(15))).toBeNull();
  });

  it('pode ultrapassar 100% quando vende acima do esperado', () => {
    expect(pctOfProRataTarget(600, 1000, at(15))).toBeCloseTo(120, 5);
  });
});

describe('pctOfFullDayTarget', () => {
