describe('classifyStoreRag', () => {
  const base = {
    stockOutCount: 0,
    stockLowCount: 0,
    pctMetaProRata: null,
    isLiveChannel: true,
    lastMovementAt: at(12, 50),
    now: at(13),
  };

  it('ok quando não há desvio', () => {
    const r = classifyStoreRag({ ...base, pctMetaProRata: 95 });
    expect(r.status).toBe('ok');
    expect(r.reasons).toEqual([]);
  });

  it('vermelho com item zerado em alerta', () => {
    const r = classifyStoreRag({ ...base, stockOutCount: 2 });
    expect(r.status).toBe('red');
    expect(r.reasons[0]).toContain('zerados');
  });

  it('vermelho com venda live abaixo de 50% do pró-rata', () => {
    const r = classifyStoreRag({ ...base, pctMetaProRata: 42 });
    expect(r.status).toBe('red');
    expect(r.reasons[0]).toContain('42%');
  });

  it('venda baixa NÃO derruba canal defasado (isLiveChannel=false)', () => {
    const r = classifyStoreRag({
      ...base,
      isLiveChannel: false,
      pctMetaProRata: 42,
    });
    expect(r.status).toBe('ok');
  });

  it('âmbar com itens abaixo do mínimo', () => {
    const r = classifyStoreRag({ ...base, stockLowCount: 3, pctMetaProRata: 90 });
    expect(r.status).toBe('amber');
    expect(r.reasons[0]).toContain('abaixo do mínimo');
  });

  it(`âmbar sem movimentação há mais de ${NO_MOVEMENT_THRESHOLD_HOURS}h na janela`, () => {
    const r = classifyStoreRag({
      ...base,
      pctMetaProRata: 90,
      lastMovementAt: null,
      now: at(13), // 4h desde a abertura sem bipagem
    });
    expect(r.status).toBe('amber');
    expect(r.reasons[0]).toContain('sem movimentação');
  });

  it('vermelho tem precedência sobre âmbar', () => {
    const r = classifyStoreRag({
      ...base,
      stockOutCount: 1,
      stockLowCount: 5,
    });
    expect(r.status).toBe('red');
  });
});

