describe('classifyStaleness', () => {
  const now = at(14);
  const minute = 60_000;

  it('fresh dentro de 2× o intervalo', () => {
    expect(classifyStaleness(at(13, 59), minute, now)).toBe('fresh');
  });

  it('stale entre 2× e 6× o intervalo', () => {
    expect(classifyStaleness(at(13, 57), minute, now)).toBe('stale');
  });

  it('very-stale a partir de 6× o intervalo', () => {
    expect(classifyStaleness(at(13, 50), minute, now)).toBe('very-stale');
  });

  it('timestamp ausente ou inválido é very-stale', () => {
    expect(classifyStaleness(null, minute, now)).toBe('very-stale');
    expect(classifyStaleness(undefined, minute, now)).toBe('very-stale');
