describe('sortAndLimitExceptions', () => {
  const exc = (
    id: string,
    severity: TvException['severity'],
    kind: TvException['kind'],
  ): TvException => ({
    id,
    kind,
    severity,
    lojaId: 1,
    lojaNome: 'Loja',
    message: id,
  });

  it('ordena vermelho antes de âmbar e limita a 7 com excedente', () => {
    const items: TvException[] = [
      exc('a1', 'amber', 'stock-low'),
      exc('r1', 'red', 'stock-out'),
      exc('a2', 'amber', 'no-movement'),
      exc('r2', 'red', 'stock-out'),
      exc('a3', 'amber', 'stale-data'),
      exc('a4', 'amber', 'stock-low'),
      exc('a5', 'amber', 'stock-low'),
      exc('a6', 'amber', 'stock-low'),
      exc('a7', 'amber', 'stock-low'),
    ];
    const result = sortAndLimitExceptions(items);
    expect(result.items).toHaveLength(7);
    expect(result.totalCount).toBe(9);
    expect(result.overflowCount).toBe(2);
    expect(result.items[0].severity).toBe('red');
    expect(result.items[1].severity).toBe('red');
    // âmbar: no-movement vem antes de stock-low, stale-data por último
    expect(result.items[2].kind).toBe('no-movement');
  });

  it('lista vazia retorna estado vazio explícito', () => {
    const result = sortAndLimitExceptions([]);
    expect(result.items).toEqual([]);
    expect(result.totalCount).toBe(0);
    expect(result.overflowCount).toBe(0);
  });
});

