describe('buildStockSummary + buildStockExceptions', () => {
  const rows = [
    { loja_id: 2, quantidade_atual: 0, quantidade_minima: 5, produtoNome: 'BROWNIE' },
    { loja_id: 2, quantidade_atual: 2, quantidade_minima: 5, produtoNome: 'COOKIE' },
    { loja_id: 2, quantidade_atual: 10, quantidade_minima: 5, produtoNome: 'BOLO' }, // ok
    { loja_id: 4, quantidade_atual: null, quantidade_minima: 3, produtoNome: 'TORTA' }, // null = 0
    { loja_id: 4, quantidade_atual: 1, quantidade_minima: 0, produtoNome: 'SEM MIN' }, // sem mínimo
    { loja_id: null, quantidade_atual: 0, quantidade_minima: 5, produtoNome: 'ÓRFÃO' },
  ];

  it('classifica zerado vs abaixo do mínimo só com mínimo definido', () => {
    const summary = buildStockSummary(rows);
    expect(summary.get(2)).toMatchObject({ zerados: 1, abaixoMinimo: 1 });
    expect(summary.get(4)).toMatchObject({ zerados: 1, abaixoMinimo: 0 });
    expect(summary.size).toBe(2);
  });

  it('gera exceções com severidade e mensagem corretas', () => {
    const summary = buildStockSummary(rows);
    const nomes = new Map([
      [2, 'Asa Sul'],
      [4, 'Lago Sul'],
    ]);
    const exceptions = buildStockExceptions(summary, nomes);
    expect(exceptions).toHaveLength(3);
    const brownie = exceptions.find((e) => e.produtoNome === 'BROWNIE');
    expect(brownie?.severity).toBe('red');
    expect(brownie?.kind).toBe('stock-out');
    expect(brownie?.message).toBe('BROWNIE zerado — Asa Sul');
    const cookie = exceptions.find((e) => e.produtoNome === 'COOKIE');
    expect(cookie?.severity).toBe('amber');
    expect(cookie?.message).toBe('COOKIE abaixo do mínimo (2/5) — Asa Sul');
  });
});

describe('remapFlashLojaIds', () => {
  const flash = (lojaId: number): FlashRow => ({
    loja_id: lojaId,
    nome_loja: `Loja ${lojaId}`,
    total_vendas: 100,
    total_cupons: 10,
    ticket_medio: 10,
    caixa_aberto: true,
    ultima_atualizacao: null,
  });

  // Cenário real: edge só mapeia códigos Degust 1→4 e 2→5; o código 3
  // (BSB Shopping → loja 6) passa cru e colidiria com Asa Norte (loja 3).
  const codeToLoja = new Map([
    [1, 4],
    [2, 5],
    [3, 6],
  ]);
  const degustLojas = new Set([4, 5, 6]);

  it('mantém lojas já mapeadas e remapeia código cru', () => {
    const result = remapFlashLojaIds(
      [flash(4), flash(5), flash(3)],
      codeToLoja,
      degustLojas,
    );
    expect(result.map((r) => r.loja_id).sort()).toEqual([4, 5, 6]);
  });

  it('descarta linha não mapeável (não corrompe outra loja)', () => {
    const result = remapFlashLojaIds([flash(99)], codeToLoja, degustLojas);
    expect(result).toEqual([]);
  });
});

