import { createElement, type ReactNode } from 'react';
import { renderHook, waitFor } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { describe, it, expect, vi } from 'vitest';
import {
  TV_QUERY_INTERVALS,
  tvDashboardKeys,
  useTvDashboardData,
} from './useTvDashboardData';

// Mock leve do client Supabase: builder encadeável thenable que resolve
// sempre { data: [], error: null } e edge function com flash vazio.
vi.mock('@/integrations/supabase/client', () => {
  type QueryResult = { data: never[]; error: null };
  const CHAIN_METHODS = [
    'select',
    'eq',
    'gt',
    'gte',
    'lte',
    'in',
    'or',
    'is',
    'order',
    'limit',
  ] as const;

  const makeBuilder = (): Record<string, unknown> => {
    const builder: Record<string, unknown> = {};
    for (const method of CHAIN_METHODS) {
      builder[method] = () => builder;
    }
    builder.then = (onFulfilled: (value: QueryResult) => unknown) =>
      Promise.resolve({ data: [] as never[], error: null }).then(onFulfilled);
    return builder;
  };

  return {
    supabase: {
      from: () => makeBuilder(),
      functions: {
        invoke: async () => ({ data: { flash: [] }, error: null }),
      },
    },
  };
});

function createWrapper() {
  const client = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  });
  return ({ children }: { children: ReactNode }) =>
    createElement(QueryClientProvider, { client }, children);
}

describe('useTvDashboardData', () => {
  it('monta snapshot consolidado vazio sem crash (estado vazio confirmado)', async () => {
    const { result, unmount } = renderHook(() => useTvDashboardData(), {
      wrapper: createWrapper(),
    });

    expect(result.current.isLoading).toBe(true);

    await waitFor(() => expect(result.current.network).not.toBeNull());

    expect(result.current.isError).toBe(false);
    expect(result.current.stores).toEqual([]);
    expect(result.current.factory).toBeNull();
    expect(result.current.topProducts).toEqual([]);
    // Estado vazio de exceções explícito (spec: "Nenhum alerta")
    expect(result.current.exceptions.items).toEqual([]);
    expect(result.current.exceptions.totalCount).toBe(0);
    expect(result.current.exceptions.overflowCount).toBe(0);
    // Rede sem lojas → tudo zerado/nulo, sem divisão por zero
    expect(result.current.network).toMatchObject({
      vendasHoje: 0,
      metaDia: null,
      pctMetaProRata: null,
      deltaSemana: null,
      alertasCriticos: 0,
      lojasLive: 0,
      lojasDefasadas: 0,
    });
    // Freshness sempre presente com timestamp de geração
    expect(result.current.freshness.geradoEm).toBeTruthy();
    expect(result.current.freshness.vendasLive.expectedIntervalMs).toBe(
      TV_QUERY_INTERVALS.liveMs,
    );

    unmount();
  });

  it('expõe query keys estáveis sob o prefixo tv-dashboard', () => {
    expect(tvDashboardKeys.all).toEqual(['tv-dashboard']);
    expect(tvDashboardKeys.stock()[0]).toBe('tv-dashboard');
    expect(tvDashboardKeys.movements()[0]).toBe('tv-dashboard');
    expect(tvDashboardKeys.liveSales()[0]).toBe('tv-dashboard');
  });
});

